    int ids[] = {1, 2, 3};
    int ats[] = {0, 1, 2};
    int bts[] = {5, 4, 3};
    int priorities[] = {1, 2, 3};
    int size = 3;

    struct node *root = helper_build_process_queue(ids, ats, bts, priorities, size);
    TEST_ASSERT_NOT_NULL(root);

    // Verify initial CT, WT, TAT are zero (as set by insert)
    struct node *ptr = root;
    while (ptr != NULL) {
        TEST_ASSERT_EQUAL_INT(0, ptr->CT);
        TEST_ASSERT_EQUAL_INT(0, ptr->WT);
        TEST_ASSERT_EQUAL_INT(0, ptr->TAT);
        ptr = ptr->next;
    }

    // Target: Update node with ID 2 (non-head) with only CT non-zero.
    int target_id = 2;
    int new_ct = 100;
    int new_wt = 0;
    int new_tat = 0;

    update(&root, target_id, new_ct, new_wt, new_tat);

